<div class="ui container"><div class="ui clearing segment"><h2 class="ui left floated header"><i class="users cog blue icon"></i><div class="content">User &amp; Role OPD<div class="sub header">Kelola pengguna operasional tanpa memberi hak administrator daerah.</div></div></h2><button class="ui right floated primary button" id="newOpdUser"><i class="plus icon"></i>Tambah User</button></div><table class="ui celled striped table"><thead><tr><th>Nama</th><th>Username</th><th>Role</th><th>NIP/Kontak</th><th>Status</th><th>Aksi</th></tr></thead><tbody id="opdUserRows"><tr><td colspan="6"><div class="ui active inline loader"></div></td></tr></tbody></table></div><div class="ui modal" id="opdUserModal"><i class="close icon"></i><div class="header">Data User OPD</div><div class="content"><form class="ui form" id="opdUserForm"><input type="hidden" name="id"><div class="three fields"><div class="required field"><label>Nama</label><input name="nama"></div><div class="required field"><label>Username</label><input name="username"></div><div class="required field"><label>Email</label><input type="email" name="email"></div></div><div class="three fields"><div class="field"><label>NIP</label><input name="nip"></div><div class="field"><label>Kontak</label><input name="kontak_person"></div><div class="required field"><label>Role</label><select class="ui dropdown" name="type_user"><?php foreach($roles as $role):?><option value="<?= $role ?>"><?= ucwords(str_replace('_',' ',$role)) ?></option><?php endforeach;?></select></div></div><div class="field"><label>Password <?= '<small>(wajib saat tambah)</small>' ?></label><input type="password" name="password" minlength="8"></div><div class="ui toggle checkbox"><input type="checkbox" name="disable" value="1"><label>Nonaktifkan login</label></div></form></div><div class="actions"><button class="ui deny button">Batal</button><button class="ui primary button" id="saveOpdUser">Simpan</button></div></div><script>$(function(){const esc=v=>$('<div>').text(v??'').html(),load=()=>window.Ajax.request({url:'/user_opd/list',method:'GET',success:r=>$('#opdUserRows').html((r.data||[]).map(x=>`<tr data-row='${esc(JSON.stringify(x))}'><td><b>${esc(x.nama)}</b><br><small>${esc(x.email)}</small></td><td>${esc(x.username)}</td><td><span class="ui blue label">${esc(x.type_user)}</span></td><td>${esc(x.nip||'-')}<br>${esc(x.kontak_person||'')}</td><td>${Number(x.disable)?'<span class="ui red label">Nonaktif</span>':'<span class="ui green label">Aktif</span>'}</td><td><button class="ui mini button editOpdUser">Edit</button><button class="ui mini red basic button deleteOpdUser" data-id="${x.id}">Nonaktifkan</button></td></tr>`).join('')||'<tr><td colspan="6">Belum ada user.</td></tr>')});$('#newOpdUser').click(()=>{$('#opdUserForm')[0].reset();$('#opdUserForm [name=id]').val('');$('#opdUserModal').modal('show')});$(document).on('click','.editOpdUser',function(){const x=$(this).closest('tr').data('row');Object.entries(x).forEach(([k,v])=>$('#opdUserForm [name='+k+']').val(v));$('#opdUserModal').modal('show')});$('#saveOpdUser').click(function(){window.Ajax.request({url:'/user_opd/save',method:'POST',data:$('#opdUserForm').serialize(),success:()=>{$('#opdUserModal').modal('hide');load()}})});$(document).on('click','.deleteOpdUser',function(){if(confirm('Nonaktifkan user dan cabut seluruh penugasan?'))window.Ajax.request({url:'/user_opd/delete',method:'POST',data:{id:$(this).data('id')},success:load})});$('.ui.dropdown').dropdown();$('.ui.checkbox').checkbox();load();});</script>
